-- One-time resync of the questions/candidate_positions data with the 2026
-- questionnaire rewrite (see 0007_question_answer_types.sql for the schema
-- change). This project's data was originally seeded outside the CLI
-- migration flow, so the plain `on conflict do nothing` inserts in
-- supabase/seed.sql would silently skip every changed row (including
-- deleting q4/q8, which no longer exist) — a full replace is correct here
-- specifically because these two tables are entirely derived from
-- src/lib/data/local/questions.ts and positions.ts, never hand-edited in
-- production.
delete from candidate_positions;
delete from questions;


